/*
 * A321101  Sequence generated by: a(3*n) = 0, a(3*n+2) = 3 - a(3*n+1),
 *          a(9*n+1) = 1, a(9*n+7) = 2, a(9*n+4) = 3 - a(3*n+1), for n >= 0.
 * https://oeis.org/A321101
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr
 * Formula:   Recurrence from A321101 a(3*n) = 0 a(3*n+2) = 3 - a(3*n+1)
 *            a(9*n+1) = 1 a(9*n+7) = 2 a(9*n+4) = 3 - a(3*n+1) with the same
 *            “n” as on the left (n >= 0, a(0) = 0). This function implements
 *            the recurrence with memoisation
 * Range:     u8 n <= 200, u16 n <= 200, u32 n <= 200, u64 n <= 200,
 *            u128 n <= 200, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;      /* memoised values */
static idx_t cache_cap = 0;      /* number of entries stored */

static void ensure_cache(idx_t n)
{
    if (n + 1 <= cache_cap) return;
    idx_t new_cap = (cache_cap == 0) ? 1 : cache_cap * 2;
    while (new_cap <= n) new_cap <<= 1;   /* grow until enough */
    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cache) abort();              /* allocation failure */
    cache = new_cache;
    /* initialise new slots with a sentinel value (3) */
    for (idx_t i = cache_cap; i < new_cap; ++i) cache[i] = (seq_t)3;
    cache_cap = new_cap;
}

static seq_t internal_get(idx_t n)
{
    if (n < cache_cap && cache[n] <= 2) return cache[n];  /* cached answer */
    /* compute value */
    seq_t val;
    if (n % 3 == 0) {
        val = 0;
    } else if (n % 3 == 2) {                     /* n = 3*k + 2  */
        val = (seq_t)3 - internal_get(n - 1);    /* 3*a(3*k+1)   */
    } else { /* n % 3 == 1  */
        switch (n % 9) {
            case 1: val = 1; break;
            case 7: val = 2; break;
            case 4: val = (seq_t)3 - internal_get((n - 1) / 3); break;
            default: /* never reached for n % 3 == 1 */ return 0;
        }
    }
    /* store in cache if possible */
    if (n < cache_cap) cache[n] = val;
    return val;
}

seq_t a(idx_t n)
{
    ensure_cache(n);
    return internal_get(n);
}
